const readDrafts=()=>{try{const data=JSON.parse(localStorage.getItem('paperknow-drafts')||'[]');return Array.isArray(data)?data:[];}catch{return[];}};
function template(id,title,mode,text){const frames={writing:['绪论：背景、问题、目的与意义','理论基础与文献综述','研究设计与方法','研究结果与讨论（依据真实研究填写）','结论、局限与展望','参考文献（添加真实来源）'],proposal:['选题背景与研究意义','国内外研究现状','研究目标与问题','研究内容与技术路线','数据来源与研究方法','研究计划与预期成果','参考文献（待核验）'],summary:['界定主题与检索范围','整理主要研究方向','比较理论、方法与数据','梳理共识与争议','指出证据局限','提出值得研究的问题','完整记录来源'],course:['问题与任务背景','核心概念','资料或案例分析','讨论与个人思考','结论与参考资料'],reading:['研究问题：作者要回答什么？','研究方法：数据与设计是什么？','主要发现：证据支持哪些结论？','研究局限：适用条件是什么？','我的思考：与当前研究有何联系？','来源信息：作者、年份、DOI 或 URL'],search:['拆分核心概念与同义词','组合关键词并记录检索表达式','限定年份、学科与文献类型','记录所用数据库与日期','按研究相关性筛选','核验作者、年份、DOI 与全文许可'],review:['定位对应的章节和段落','明确导师希望解决的具体问题','准备真实资料与研究证据','记录修改内容和位置','核对逻辑、引用与格式','写出对导师意见的回应'],rewrite:['保留论点、术语、数据与引用','删减重复表述与套话','补充自己的分析和真实证据','调整逻辑与句子结构','逐句核对原意'],reduce:['检查笼统判断是否有具体依据','加入自己的研究过程与分析','核对段落与研究问题的关联','保留真实引用、数据与结论','避免只替换近义词'],translation:['记录原文与研究语境','建立术语表（原文 / 译文 / 来源）','填写译文（当前未调用翻译模型）','逐项核对数字、单位、否定与限定词','核对术语一致性与来源'],ppt:['封面：题目、姓名与院系','研究背景与核心问题','文献回顾与研究切入点','研究方法与数据','研究结果（待填实际证据）','讨论、贡献与局限','结论与未来方向','致谢与问答'],format:['封面与声明','中英文摘要及关键词','目录与章节编号','字体、行距、页边距、页码','图表编号、标题与单位','引文与参考文献格式','附录与致谢','以学校或期刊最新要求核对'],journal:['核对目标期刊征稿范围','核对文章类型、语言和篇幅','准备正文、图表与数据说明','准备投稿信与作者贡献','核对伦理、利益冲突与版权要求','记录投稿与返修节点'],resume:['个人资料与联系方式','教育背景','研究方向与项目经历','真实论文、报告与作品','专业技能','获奖与其他经历']};
if(id==='aigc')return `${title}\n${mode} · 报告结构预览\n\n检测状态：未执行\nAI 率检测服务：尚未接入\n检测范围、段落提示、结果解释：待实际服务返回\n\n当前不提供 AIGC 百分比或检测结论。`;
if(id==='topic')return `${title} · ${mode}\n\n1. ${title}的应用现状与发展路径研究\n2. ${title}的影响因素及作用机制研究\n3. ${title}的实践困境与优化策略研究\n\n以上为按输入方向组合的选题模板，请结合资料与导师意见判断可行性。`;
return `${title}\n${mode} · ${id==='writing'?'论文大纲':'结构模板'}\n\n${(frames[id]||frames.writing).map((s,i)=>`${i+1}. ${s}`).join('\n\n')}${text?'\n\n已提供的材料 / 要求：\n'+text:''}\n\n此为本地结构模板，未调用 AI、检索文献或分析上传文档。`;
}
export function mountTool(id,draftId,projectId){if(id==='writing'){mountWriting(draftId,projectId);return true;}document.querySelector('.dashboard').classList.remove('creation-page');const config=toolConfigs[id];if(!config)return false;const [name,desc,label,modes]=config,loaded=readDrafts().find(d=>String(d.id)===String(draftId));let savedId=loaded?.id||null,result='';document.querySelector('.breadcrumb strong').textContent=name;document.querySelectorAll('.sidebar .nav-link').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#category/${({writing:'writing',topic:'writing',proposal:'writing',summary:'writing',course:'writing',review:'writing',rewrite:'rewrite',reduce:'reduce',aigc:'aigc',ppt:'ppt',research:'research',search:'research',format:'format',reading:'more',translation:'more',journal:'more',resume:'more'})[id]}`));document.querySelector('.dashboard').innerHTML=`<div class="tool-page-heading"><div><span class="overline">PAPERKNOW RESEARCH WORKSPACE</span><h1>${name}</h1><p>${desc}</p></div><a class="btn secondary" href="/workspace.html">返回工作台</a></div>${writingTasks.some(t=>t[0]===id)?taskNav(id):''}<div class="tool-boundary">${id==='research'?'本地绘图 · 图表来自你输入的数据':id==='writing'?'本地大纲模板 · 可编辑、保存与导出':'本地流程体验 · AI 与在线服务尚未接入'}</div><div class="tool-editor-grid"><section class="card tool-input-card"><h2>${id==='research'?'填写图表数据':'填写内容'}</h2><form id="integrated-form"><label class="field-label" for="integrated-project">所属项目（可选）</label><select id="integrated-project"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===(loaded?.projectId||projectId)?'selected':''}>${esc(p.name)}${p.status==='archived'?'（已归档）':''}</option>`).join('')}</select><label class="field-label" for="integrated-mode">${id==='writing'?'写作类型':'使用场景'}</label><select id="integrated-mode">${modes.map(m=>`<option ${m===loaded?.mode?'selected':''}>${m}</option>`).join('')}</select><label class="field-label" for="integrated-title">${id==='topic'?'研究方向':'题目 / 主题'}</label><input id="integrated-title" required minlength="2" maxlength="150" placeholder="例如：人工智能辅助课堂学习研究" value="${esc(loaded?.title||'')}">${id==='writing'?`<div class="integrated-row"><div><label class="field-label" for="integrated-degree">学段 / 身份</label><select id="integrated-degree">${['专科论文','本科论文','硕士论文','博士论文','期刊论文','SCI论文'].map(d=>`<option ${d===(loaded?.degree||'本科论文')?'selected':''}>${d}</option>`).join('')}</select></div><div><label class="field-label" for="integrated-major">学科专业</label><input id="integrated-major" maxlength="100" placeholder="例如：教育学" value="${esc(loaded?.major||'')}"></div></div>`:''}<label class="field-label" for="integrated-text">${id==='research'?'数据（每行：名称,非负数值）':'材料 / 正文 / 补充要求（可选）'}</label><textarea id="integrated-text" rows="8" maxlength="20000" placeholder="${id==='research'?'传统课堂,65\n混合学习,78\n个性化学习,91':'粘贴需要整理的内容或填写具体要求…'}">${id==='research'?'传统课堂,65\n混合学习,78\n个性化学习,91':''}</textarea><p class="field-note">${id==='research'?'最多 8 组数据。':'此处不会上传文件或发送正文；文档解析请使用论文查重。'}</p><div class="error-text" id="integrated-error" role="alert"></div><button class="btn primary full" type="submit">${label}</button></form></section><section class="card tool-output-card"><div class="dashboard-section-title"><h2>${id==='research'?'图表预览':'内容与编辑'}</h2><span class="badge neutral">${id==='research'?'本地生成':'模板体验'}</span></div><div id="integrated-chart" hidden></div><textarea id="integrated-result" rows="20" aria-label="编辑当前结果" placeholder="结果将在这里显示，生成后可直接编辑。"></textarea><div class="integrated-actions"><button class="btn secondary" id="integrated-save" hidden>保存到我的创作</button><button class="btn primary" id="integrated-export" hidden>${id==='research'?'导出 SVG':'导出文本'}</button></div><p id="integrated-status" role="status" class="field-note"></p></section></div>`;
if(loaded){document.querySelector('#integrated-text').value=loaded.material||'';const div=document.createElement('div');div.innerHTML=loaded.html;div.querySelectorAll('p,h3,h4').forEach(n=>n.append(document.createTextNode('\n')));document.querySelector('#integrated-result').value=loaded.text||div.textContent;document.querySelector('#integrated-save').hidden=false;document.querySelector('#integrated-export').hidden=false;}
document.querySelector('#integrated-form').addEventListener('submit',e=>{e.preventDefault();const title=document.querySelector('#integrated-title').value.trim(),text=document.querySelector('#integrated-text').value.trim(),mode=document.querySelector('#integrated-mode').value;document.querySelector('#integrated-error').textContent='';if(!title){document.querySelector('#integrated-error').textContent='请填写题目或主题。';return;}if(id==='research'){const rows=text.split('\n').map(l=>l.split(/[,，]/).map(v=>v.trim()));if(!text||rows.length>8||rows.some(r=>r.length!==2||!r[0]||r[1]===''||!Number.isFinite(Number(r[1]))||Number(r[1])<0)){document.querySelector('#integrated-error').textContent='请输入 1–8 组数据，每行填写名称和非负数值。';return;}const max=Math.max(1,...rows.map(r=>Number(r[1])));result=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 440" width="760" height="440"><rect width="760" height="440" fill="white"/><text x="30" y="40" font-size="23" font-family="sans-serif" fill="#223c60">${esc(title)}</text>${rows.map(([n,v],i)=>{const x=40+i*680/rows.length,h=Number(v)/max*260;return `<rect x="${x}" y="${345-h}" width="${Math.min(65,480/rows.length)}" height="${h}" rx="4" fill="#347aff"/><text x="${x}" y="${330-h}" font-size="14" font-family="sans-serif" fill="#597694">${esc(v)}</text><text x="${x}" y="380" font-size="12" font-family="sans-serif" fill="#597694">${esc(n)}</text>`;}).join('')}</svg>`;document.querySelector('#integrated-chart').innerHTML=result;document.querySelector('#integrated-chart').hidden=false;document.querySelector('#integrated-result').hidden=true;}else{document.querySelector('#integrated-result').value=template(id,title,mode,text)+(id==='writing'?'\n\n学段 / 身份：'+document.querySelector('#integrated-degree').value+'\n学科专业：'+(document.querySelector('#integrated-major').value.trim()||'待填写'):'');document.querySelector('#integrated-save').hidden=false;}document.querySelector('#integrated-export').hidden=false;document.querySelector('#integrated-status').textContent=id==='research'?'图表已根据当前数据生成。':'模板已生成，可直接编辑后保存。';});
document.querySelector('#integrated-save').addEventListener('click',()=>{const text=document.querySelector('#integrated-result').value.trim();if(!text)return;const title=document.querySelector('#integrated-title').value.trim()||name;const item={projectId:document.querySelector('#integrated-project').value,material:document.querySelector('#integrated-text').value,updatedAt:new Date().toISOString(),id:savedId||Date.now(),title,degree:document.querySelector('#integrated-degree')?.value||name,major:document.querySelector('#integrated-major')?.value||'',html:text.split('\n').map(l=>`<p>${esc(l)}</p>`).join(''),text,mode:document.querySelector('#integrated-mode').value,tool:id,date:new Date().toLocaleString('zh-CN')};const drafts=readDrafts(),index=drafts.findIndex(d=>d.id===item.id);if(index>=0)drafts[index]=item;else drafts.unshift(item);try{localStorage.setItem('paperknow-drafts',JSON.stringify(drafts));savedId=item.id;document.querySelector('#integrated-status').textContent='已保存到当前浏览器，可从我的成果继续编辑。';try{recordTask({id:'draft-'+item.id,title:item.title,kind:name+' · 本地保存',status:'completed',url:'#draft/'+item.id});}catch{document.querySelector('#integrated-status').textContent+=' 任务记录未保存。';}}catch{document.querySelector('#integrated-status').textContent='保存失败，请导出备份。';}});
document.querySelector('#integrated-export').addEventListener('click',()=>{const content=id==='research'?result:document.querySelector('#integrated-result').value;if(!content)return;const type=id==='research'?'image/svg+xml;charset=utf-8':'text/plain;charset=utf-8',url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=(document.querySelector('#integrated-title').value||name).replace(/[\\/:*?"<>|]/g,'_')+(id==='research'?'.svg':'.txt');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});return true;
}
